// Shared by the engine's files (engine.h is what the effects see).

#pragma once

#include "engine/engine.h"

// The version of a kernel for one API: Halide's generic entry point (one pointer per
// argument: the halide_buffer_t of an image, the address of a value) and the description
// of its arguments.
typedef struct {
    int (*argv)(void **args);
    const struct halide_filter_metadata_t *(*metadata)(void);
} MsKernelVersion;

typedef struct {
    const char *name;
    MsKernelVersion versions[MS_API_COUNT]; // NULL where not built
} MsKernelEntry;

// Every kernel (generated by CMakeLists.txt: kernels.c).
extern const MsKernelEntry ms_kernel_table[MS_KERNEL_COUNT];

// Makes Halide's runtime errors return an error status instead of aborting the host, and
// limits the threads of its CPU kernels (kernel.c). Called before any call into Halide.
void ms_catch_errors(void);

// The device interface of a GPU API built here; NULL for the CPU.
const struct halide_device_interface_t *ms_device_interface(MsApi api);

// GPU memory kept between renders (pool.c). ms_pool_take gives `b` kept memory of
// `interface` if some fits; ms_pool_park takes `b`'s GPU memory away from it, kept for the
// next renders (`keep`) or freed.
void ms_pool_take(halide_buffer_t *b, const struct halide_device_interface_t *interface);
void ms_pool_park(halide_buffer_t *b, int keep);
void ms_pool_free_all(void);

// Page-locking host images for the CUDA copies (pin.c; nothing without CUDA). The context:
// that of `gpu`'s GPU memory (Halide's), NULL when page-locking is off or impossible. ms_pin
// locks the memory of `b` (1), or does nothing (0: copied as it is); ms_unpin releases it.
typedef struct {
    void *start;
} MsPinned;
void *ms_pin_context(const halide_buffer_t *gpu);
int ms_pin(MsPinned *p, const halide_buffer_t *b, void *context);
void ms_unpin(MsPinned *p, void *context);
